def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C' if history[-1][1] == 'C' else 'D'
    if n == 3:
        return 'C' if history[-1][1] == 'C' else 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_def = 0
    for a in opp:
        if a == 'D':
            opp_def += 1
    me_def = 0
    for a in me:
        if a == 'D':
            me_def += 1
    last_me, last_opp = history[-1]

    if n >= 198:
        return 'D'
    if n >= 190:
        return 'D'

    recent_len = 6 if n >= 6 else n
    recent = opp[-recent_len:]
    recent_def = 0
    for a in recent:
        if a == 'D':
            recent_def += 1

    opp_rate3 = opp_def * 3
    if opp_rate3 >= n * 2:
        if recent_def == recent_len:
            return 'D'
        if last_opp == 'C' and rng.random() < 0.08:
            return 'C'
        return 'D'

    if opp_def == 0:
        if n >= 150 and rng.random() < 0.25:
            return 'D'
        return 'C'

    if last_opp == 'D':
        run = 1
        i = n - 2
        while i >= 0 and opp[i] == 'D':
            run += 1
            i -= 1
        if run >= 3:
            return 'D'
        if run == 2:
            if rng.random() < 0.18:
                return 'C'
            return 'D'
        if opp_def * 4 <= n:
            if rng.random() < 0.35:
                return 'C'
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    if last_opp == 'C':
        if n >= 12 and me_def > 0:
            recent_me = me[-4:]
            if 'D' in recent_me:
                return 'C'
        if opp_def * 5 > n and rng.random() < 0.18:
            return 'D'
        if opp_def * 8 <= n and n >= 60 and rng.random() < 0.12:
            return 'D'
        return 'C'

    return 'C'
